export async function readSellerClientFile({ directory, exportId, file, expectedManifestSha256 } = {}) {
  if (![CLIENT_EXPORT_MANIFEST, ...CLIENT_EXPORT_FILES].includes(file) || !validSha(expectedManifestSha256))
